            hop@.instance_id() == old(self).instance@.id(),
            hop@.key() == old(self).page_id@,
    {
        let tracked mut heap_of_page;
        atomic_with_ghost!(
            &self.atomic => no_op();
            ghost g => {
            }
        );
        Tracked(heap_of_page)
    }
}

